def __init__(self, cfg_dict=None, cfg_text=None, filename=None, **kwargs):
    if cfg_dict is None:
        cfg_dict = dict(kwargs)
    elif not isinstance(cfg_dict, dict):
        raise TypeError('cfg_dict must be a dict, but '
                        f'got {type(cfg_dict)}')
    for key in cfg_dict:
        if key in RESERVED_KEYS:
            raise KeyError(f'{key} is reserved for config file')

    if isinstance(filename, Path):
        filename = str(filename)

    super().__setattr__('_cfg_dict', ConfigDict(cfg_dict))
    super().__setattr__('_filename', filename)
    if cfg_text:
        text = cfg_text
    elif filename:
        with open(filename) as f:
            text = f.read()
    else:
        text = ''
    super().__setattr__('_text', text)

def add_scalar(batch, value, name) -> Union[torch.Tensor, np.ndarray]:
    if isinstance(batch, (tuple, list)):
        for b in batch:
            add_scalar(b, value, name)

    if isinstance(batch, dict):
        batch[name] = torch.tensor(value)
        batch['meta'][name] = torch.tensor(value)
    return batch

def __iter__(self):
    iteration = self.start_iter
    while iteration <= self.num_iterations:
        for batch in self.batch_sampler:
            iteration += 1
            if iteration > self.num_iterations:
                break
            yield batch

def __init__(self, network: nn.Module = None, **kwargs) -> None:
    super().__init__()
    self.unregistered = [network]

    # Prepare fake forward sample function
    # Hacky forward function definition
    def sample(self, *args, **kwargs):
        if not len(kwargs): batch = args[-1]
        else: batch = kwargs.pop('batch', dotdict())
        self.forward(batch)
        return None, None, None, None
    if not hasattr(self, 'sample'): self.sample = MethodType(sample, self)
    if not hasattr(self, 'render'): self.render = MethodType(sample, self)
    if not hasattr(self, 'compute'): self.compute = MethodType(sample, self)

def sample(self, *args, **kwargs):
    if not len(kwargs): batch = args[-1]
    else: batch = kwargs.pop('batch', dotdict())
    self.forward(batch)
    return None, None, None, None

def __iter__(self) -> Iterator[int]:
    n = len(self.data_source)
    if self.generator is None:
        seed = int(torch.empty((), dtype=torch.int64).random_().item())
        generator = torch.Generator()
        generator.manual_seed(seed)
    else:
        generator = self.generator

    for i in range(self.num_samples):
        if i < self.num_warmups:
            # Randomly sample from range [0, n * i / self.num_warmups)
            idx = random.choice(range(0, max(int(n * i / self.num_warmups), 3)))
        else:
            # Randomly sample from range [0, n)
            idx = random.randrange(n)
        yield self.inds[idx]

