def pad_image_to_divisor(img: torch.Tensor, div: List[int], mode='constant', value=0.0):
    H, W = img.shape[-2:]
    H = (H + div[0] - 1) // div[0] * div[0]
    W = (W + div[0] - 1) // div[0] * div[0]
