def weight_regression(depth_prob: torch.Tensor, depth_values: torch.Tensor = None, use_dist: bool = False):
    B, D, H, W = depth_prob.shape
    raws = depth_prob.permute(0, 2, 3, 1).view(B, H * W, D)  # B, H, W, D -> B, HW, D
    if use_dist:
        z_vals = depth_values.permute(0, 2, 3, 1).view(B, H * W, D)  # B, H, W, D -> B, HW, D
        dists = compute_dist(z_vals)  # B, HW, D
        occ = 1. - torch.exp(-raws * dists)  # B, HW, D
    else:
        occ = 1. - torch.exp(-raws)  # B, HW, D
    weights = render_weights(occ)  # B, HW, D
    return weights.view(B, H, W, D).permute(0, 3, 1, 2)

def compute_dist(z_vals: torch.Tensor, dist_default: float = -1.0):
    if dist_default < 0:
        dist = z_vals[..., 1:] - z_vals[..., :-1]  # (B, P, S - 1)
        dist = torch.cat([dist, dist[..., -1:]], dim=-1)  # (B, P, S)
    else:
        dist = torch.full_like(z_vals, dist_default)  # (B, P, S)
    dist = dist.clip(0)  # sometimes sampled points are sooo close on a ray that the computed dists is ever so slightly negative
    return dist

def linearize_depth(d, n: float, f: float):
    # 0-1 -> -1,1
    # ndc -> view
    return (2.0 * n * f) / (f + n - (d * 2 - 1) * (f - n))

