        depth, scale = read_pfm(depth_file)
        depth = depth / scale
        if depth.ndim == 2:
            depth = depth[..., None]  # H, W, 1
        depth = depth[..., :1]
    elif depth_file.endswith('.hdr') or depth_file.endswith('.exr'):
