    if not len(faces):
        verts, colors, normals, scalars = load_pts(filename)
        self.render_type = Mesh.RenderType.POINTS
    else:
        self.render_type = Mesh.RenderType(faces.shape[-1])  # use value
    return verts, faces, colors, normals, scalars

