    return 0.6258357354491761 * (x2 * (x2 - 3.0 * y2) - y2 * (3.0 * x2 - y2))

def EvalSH(l: int, m: int, dirs: torch.Tensor) -> torch.Tensor:
    """
    Args:
      dirs: array [..., 3]. works with torch/jnp/np
    Return:
      array [...]
    """
    # Validate l and m here (don't do it generally since EvalSHSlow also
    # checks it if we delegate to that function).
    assert l >= 0, "l must be at least 0."
    assert -l <= m and m <= l, "m must be between -l and l."
    dx = dirs[..., 0]
    dy = dirs[..., 1]
    dz = dirs[..., 2]

    if l == 0:
        return HardcodedSH00(dx, dy, dz)
    elif l == 1:
        if m == -1:
            return HardcodedSH1n1(dx, dy, dz)
        elif m == 0:
            return HardcodedSH10(dx, dy, dz)
        elif m == 1:
            return HardcodedSH1p1(dx, dy, dz)
        else:
            raise NotImplementedError
    elif l == 2:
        if m == -2:
            return HardcodedSH2n2(dx, dy, dz)
        elif m == -1:
            return HardcodedSH2n1(dx, dy, dz)
        elif m == 0:
            return HardcodedSH20(dx, dy, dz)
        elif m == 1:
            return HardcodedSH2p1(dx, dy, dz)
        elif m == 2:
            return HardcodedSH2p2(dx, dy, dz)
        else:
            raise NotImplementedError
    elif l == 3:
        if m == -3:
            return HardcodedSH3n3(dx, dy, dz)
        elif m == -2:
            return HardcodedSH3n2(dx, dy, dz)
        elif m == -1:
            return HardcodedSH3n1(dx, dy, dz)
        elif m == 0:
            return HardcodedSH30(dx, dy, dz)
        elif m == 1:
            return HardcodedSH3p1(dx, dy, dz)
        elif m == 2:
            return HardcodedSH3p2(dx, dy, dz)
        elif m == 3:
            return HardcodedSH3p3(dx, dy, dz)
        else:
            raise NotImplementedError
    elif l == 4:
        if m == -4:
            return HardcodedSH4n4(dx, dy, dz)
        elif m == -3:
            return HardcodedSH4n3(dx, dy, dz)
        elif m == -2:
            return HardcodedSH4n2(dx, dy, dz)
        elif m == -1:
            return HardcodedSH4n1(dx, dy, dz)
        elif m == 0:
            return HardcodedSH40(dx, dy, dz)
        elif m == 1:
            return HardcodedSH4p1(dx, dy, dz)
        elif m == 2:
            return HardcodedSH4p2(dx, dy, dz)
        elif m == 3:
            return HardcodedSH4p3(dx, dy, dz)
        elif m == 4:
            return HardcodedSH4p4(dx, dy, dz)
        else:
            raise NotImplementedError
    else:
        raise NotImplementedError

def callable_from_cfg(func: Callable):
    def inner(*args, **kwargs):
        if len(args): cfg: dict = args[0]
        elif 'cfg' in kwargs: cfg: dict = kwargs['cfg']
        else: return func(*args, **kwargs)
        cfg.update(kwargs)
        return call_from_cfg(func, cfg)
    return inner

def inner(*args, **kwargs):
    if len(args): cfg: dict = args[0]
    elif 'cfg' in kwargs: cfg: dict = kwargs['cfg']
    else: return func(*args, **kwargs)
    cfg.update(kwargs)
    return call_from_cfg(func, cfg)

def batch_aware_indexing(mask: torch.Tensor, metric: torch.Tensor = None, dim=-1) -> Tuple[torch.Tensor, torch.Tensor, int]:  # MARK: SYNC
    # dim: in terms of the index (mask)
    if mask.dtype != torch.bool: mask = mask.bool()
    if metric is None: metric = mask.int()
    if metric.dtype == torch.bool: metric = metric.int()
    # retain all other dimensions (likely batch dimensions)
    S = mask.sum(dim=dim).max().item()  # the max value of this dim on all other dimension
    valid, inds = metric.topk(S, dim=dim, sorted=False)  # only find the top (mask = True) values (randomly select other values)
    return valid, inds, S

def multi_indexing(indices: torch.Tensor, shape: torch.Size, dim=-2):
    # index will first be augmented to match the values' dimentionality at the back
    # then we will try to broatcast index's shape to values shape
    shape = list(shape)
    back_pad = len(shape) - indices.ndim
    for _ in range(back_pad): indices = indices.unsqueeze(-1)
    expand_shape = shape
    expand_shape[dim] = -1
    return indices.expand(*expand_shape)

def multi_scatter(target: torch.Tensor, indices: torch.Tensor, values: torch.Tensor, dim=-2):
    # backward of multi_gather
    return target.scatter(dim, multi_indexing(indices, values.shape, dim), values)

def multi_scatter_(target: torch.Tensor, indices: torch.Tensor, values: torch.Tensor, dim=-2):
    # inplace version of multi_scatter
    return target.scatter_(dim, multi_indexing(indices, values.shape, dim), values)

def linear_indexing(indices: torch.Tensor, shape: torch.Size, dim=0):
    assert indices.ndim == 1
    shape = list(shape)
    dim = dim if dim >= 0 else len(shape) + dim
    front_pad = dim
    back_pad = len(shape) - dim - 1
    for _ in range(front_pad): indices = indices.unsqueeze(0)
    for _ in range(back_pad): indices = indices.unsqueeze(-1)
    expand_shape = shape
    expand_shape[dim] = -1
    return indices.expand(*expand_shape)

def deformation_gradient(tris: torch.Tensor, Dm_invs: torch.Tensor):
    Ds = get_shape_matrix(tris)
    return Ds @ Dm_invs

def green_strain_tensor(F: torch.Tensor) -> torch.Tensor:
    I = get_matching_identity_matrix(F)
    return 0.5 * (F.mT @ F - I)

def bending_energy_constraints(v: torch.Tensor, garment: Garment, **kwargs):
    # XPBD step
    triangles = multi_gather_tris(v, garment.f_connected_faces.view(-1, 3)).view(v.shape[0], -1, 2 * 3, 3)  # B, E, 2 * 3, 3
    inv_mass = multi_gather_tris(garment.inv_mass[None, ..., None], garment.f_connected_faces.view(-1, 3))[..., 0].view(v.shape[0], -1, 2 * 3)  # B, E, 2 * 3

    def func(triangles, garment): return bending_energy_components(v, triangles.view(v.shape[0], -1, 2, 3, 3), garment)
    return xpbd_constraints(func, triangles, inv_mass, garment, **kwargs)

def linear_gather(values: torch.Tensor, indices: torch.Tensor, dim=0):
    # only taking linear indices as input
    return values.gather(dim, linear_indexing(indices, values.shape, dim))

def semantics_to_color(semantic: torch.Tensor,  # V,
                       palette: torch.Tensor,  # 256, 3
                       ):
    return linear_gather(palette, semantic)  # V, 3

def get_edge_length(v, e):
    v0 = linear_gather(v, e[..., 0], dim=-2)
    v1 = linear_gather(v, e[..., 1], dim=-2)
    return torch.norm(v0 - v1, dim=-1)

def expand_at_the_back(target: torch.Tensor, inds: torch.Tensor):
    for _ in range(target.ndim - 1):
        inds = inds.unsqueeze(-1)
    inds = inds.expand(-1, *target.shape[1:])
    return inds

def get_bound_2d_bound(bounds: torch.Tensor, K: torch.Tensor, R: torch.Tensor, T: torch.Tensor, H, W, pad=25):  # pad more, be safe
    if bounds.ndim == 3: corners_3d = torch.stack([get_bound_corners(b) for b in bounds])
    else: corners_3d = get_bound_corners(bounds)
    if isinstance(H, torch.Tensor): H = H.item()
    if isinstance(W, torch.Tensor): W = W.item()
    corners_2d = project(corners_3d, K, R, T)
    corners_2d = corners_2d.round().int()

    x_min = (corners_2d[..., 0].min() - pad).clip(0, W)
    x_max = (corners_2d[..., 0].max() + pad).clip(0, W)
    y_min = (corners_2d[..., 1].min() - pad).clip(0, H)
    y_max = (corners_2d[..., 1].max() + pad).clip(0, H)
    x, y, w, h = x_min, y_min, x_max - x_min, y_max - y_min

    return x, y, w, h

def get_shape_matrix(tris: torch.Tensor):
    return torch.stack([tris[..., 0, :] - tris[..., 2, :],
                        tris[..., 1, :] - tris[..., 2, :],
                        ], dim=-1)

def coords_to_indices(ij: torch.Tensor, H, W):
    i, j = ij.unbind(-1)
    return i * W + j  # ... (no last dim)

def extract_weights(mesh: bpy.types.Object, bone_names=[]):
    """
    export skin weights on selected character
    """
    vertex_groups = mesh.vertex_groups
    vertices = mesh.data.vertices
    vertex_ids = [v.index for v in vertices]

    # assuming bone names to go up like 0, 1, 2...
    weights = np.zeros(shape=(len(vertex_ids), len(vertex_groups) if not bone_names else len(bone_names)))

    for vertex_id in tqdm(vertex_ids):
        for grp in vertices[vertex_id].groups:
            if bone_names:
                vertex_group_name = vertex_groups[grp.group].name
                if vertex_group_name in bone_names:
                    bone = bone_names.index(vertex_group_name)
                else:
                    continue  # filter
            else:
                bone = grp.group
            weight = grp.weight
            weights[int(vertex_id), int(bone)] = weight

    weights = weights / weights.sum(axis=-1, keepdims=True)
    return weights

def assign_bw(mesh: bpy.types.Object, weights, bone_ids):
    # note that bones are marked by ids, should correspond with vertex group
    for v, bw in enumerate(tqdm(weights)):
        for i, bone_id in enumerate(bone_ids[v]):
            if bw[i] > 0:
                bone_name = str(bone_id)  # might already be a string
                if bone_name not in mesh.vertex_groups:
                    # !: Let's hope from_pydata won't change the indices
                    g = mesh.vertex_groups.new(name=bone_name)
                g = mesh.vertex_groups[bone_name]
                g.add([v], bw[i], 'REPLACE')

