def quaternion_to_angle_axis(x: float, y: float, z: float, w: float):
    if w == 1:
        return np.array([x, y, z])
    angle = 2 * np.arccos(w)
    angle_axis = np.array([x, y, z]) / np.sin(angle / 2) * angle  # quaternion to angle axis
    return angle_axis

