def replace_tensor_to_optimizer(self, tensor, name):
    optimizable_tensors = {}
    for group in self.optimizer.param_groups:
        if group["name"] == name:
            stored_state = self.optimizer.state.get(group['params'][0], None)
            stored_state["exp_avg"] = torch.zeros_like(tensor)
            stored_state["exp_avg_sq"] = torch.zeros_like(tensor)

            del self.optimizer.state[group['params'][0]]
            group["params"][0] = nn.Parameter(tensor.requires_grad_(True))
            self.optimizer.state[group['params'][0]] = stored_state

            optimizable_tensors[group["name"]] = group["params"][0]
    return optimizable_tensors

def _prune_optimizer(self, mask: torch.Tensor):
    optimizable_tensors = {}
    for group in self.optimizer.param_groups:
        stored_state = self.optimizer.state.get(group['params'][0], None)
        if stored_state is not None:
            stored_state["exp_avg"] = stored_state["exp_avg"][mask]
            stored_state["exp_avg_sq"] = stored_state["exp_avg_sq"][mask]

            del self.optimizer.state[group['params'][0]]
            group["params"][0] = nn.Parameter((group["params"][0][mask].requires_grad_(True)))
            self.optimizer.state[group['params'][0]] = stored_state

            optimizable_tensors[group["name"]] = group["params"][0]
        else:
            group["params"][0] = nn.Parameter(group["params"][0][mask].requires_grad_(True))
            optimizable_tensors[group["name"]] = group["params"][0]
    return optimizable_tensors

def optimize_until_no_nan(func: Callable[..., torch.Tensor], *args: torch.Tensor):
    # Note: assuming first value in args is to be optimized and can be NaN
    # FIXME: nasty fix for nan: repeating until it's not a nan anymore, while True is bad...
    param_to_optim = args[0]
    while True:

        param_to_optim = func(
            param_to_optim.clone(), *args[1:]
        )

        if param_to_optim.isnan().any():
            log("nan detected, repeating grid optimization step...", 'red')
            continue
        else:
            break
    return param_to_optim

def _set_optimizer_lr(optimizer, values):
    for param_group in optimizer.param_groups:
        param_group['lr'] = values[param_group['name']]

def _get_optimizer_lr(optimizer):
    values = dotdict()
    for param_group in optimizer.param_groups:
        values[param_group['name']] = param_group['lr']
    return values

def step(self, epoch=None):
    if self.last_epoch != -1:
        values = self._get_optimizer_lr(self.optimizer)
        for name, sched in self.schedulers.items():
            sched.step()
            values[name] = self._get_optimizer_lr(self.optimizer)[name]
            self._set_optimizer_lr(self.optimizer, values)
    super().step()

def reflect(ray_d: torch.Tensor, norm: torch.Tensor):
    dot = (ray_d * norm).sum(dim=-1, keepdim=True)
    return 2 * (norm * dot) - ray_d

def read(self, key, dt='mat'):
    if dt == 'mat':
        output = self.fs.getNode(key).mat()
    elif dt == 'list':
        results = []
        n = self.fs.getNode(key)
        for i in range(n.size()):
            val = n.at(i).string()
            if val == '':
                val = str(int(n.at(i).real()))
            if val != 'none':
                results.append(val)
        output = results
    elif dt == 'real':
        output = self.fs.getNode(key).real()
    else:
        raise NotImplementedError
    return output

