def raw2alpha(raws: torch.Tensor, dists=0.005, bias=0.0):
    if isinstance(dists, torch.Tensor):
        if dists.ndim == raws.ndim - 1:
            dists = dists[..., None]
    return 1. - torch.exp(-(raws + bias) * dists)

def sdf_to_sigma(sdf: torch.Tensor, beta: torch.Tensor):
    # double the computation, but no synchronization needed
    x = -sdf
    ind0 = x <= 0
    ind1 = ~ind0

    return compute_val0(x, beta, ind0) + compute_val1(x, beta, ind1)

def grid_sample(input: torch.Tensor, grid: torch.Tensor, *args, **kwargs) -> torch.Tensor:
    # https://github.com/pytorch/pytorch/issues/34704
    # RuntimeError: derivative for grid_sampler_2d_backward is not implemented
    # this implementation might be slower than the cuda one
    if args or kwargs:
        # warnings.warn(message=f'unused arguments for grid_sample: {args}, {kwargs}')
        return F.grid_sample(input, grid, *args, **kwargs)
    if input.ndim == 3:
        # invoke 1d grid_sampling that falls through
        assert grid.ndim == 3, '3d input needs a 3d grid'
        return grid_sample_1d(input, grid, args, kwargs)
    elif input.ndim == 4:
        # invoke 2d custom grid_sampling
        assert grid.ndim == 4, '4d input needs a 4d grid'
        return grid_sample_2d(input, grid)
    elif input.ndim == 5:
        # invoke 3d custom grid_sampling
        assert grid.ndim == 5, '5d input needs a 5d grid'
        return grid_sample_3d(input, grid)
    else:
        raise NotImplementedError(f'grid_sample not implemented for {input.ndim}d input')

def matchup_channels(t: torch.Tensor, w: torch.Tensor):
    if t.ndim == w.ndim + 1:
        t = t[..., 0]  # remove last dimension
    if t.shape[-1] != w.shape[-1] + 1:
        t = torch.cat([t, torch.ones_like(t[..., -1:])], dim=-1)  # 65
    return t, w

def weight_to_pdf(t: torch.Tensor, w: torch.Tensor, eps=torch.finfo(torch.float32).eps**2):
    t, w = matchup_channels(t, w)
    """Turn a vector of weights that sums to 1 into a PDF that integrates to 1."""
    return w / (t[..., 1:] - t[..., :-1]).clip(eps)

def pdf_to_weight(t: torch.Tensor, p: torch.Tensor):
    t, p = matchup_channels(t, p)
    """Turn a PDF that integrates to 1 into a vector of weights that sums to 1."""
    return p * (t[..., 1:] - t[..., :-1])

def col2imu32(col: np.uint32 = 0xff3355ff):
    r = col >> 24 & 0xff
    g = col >> 16 & 0xff
    b = col >> 8 & 0xff
    a = col >> 0 & 0xff
    return np.uint32(a << 24 | b << 16 | g << 8 | r)

