def train(self):  # from begin epoch
    epoch = self.load_model()

    # The actual training for this epoch
    train_generator = self.train_generator(epoch, self.ep_iter)  # yield every ep iter

    # train the network
    for epoch in range(epoch, self.epochs):

        # Possible to make this a decorator?
        next(train_generator)  # avoid reconstruction of the dataloader

        # Leave some breathing room for other applications
        if (epoch + 1) % self.empty_cache_ep == 0:
            log(green(f'Emptying cuda memory cache'))
            torch.cuda.empty_cache()
            log('Current memory info:', {
                'mem': torch.cuda.memory_allocated() / 2**20,
                'max_mem': torch.cuda.max_memory_allocated() / 2**20,
                'mem_cache': torch.cuda.memory_cached() / 2**20,
                'mem_reserved': torch.cuda.memory_reserved() / 2**20,
            })

        # Saving stuff to disk
        if (epoch + 1) % self.save_ep == 0 and not get_rank():
            try:
                self.save_model(epoch, latest=False)
            except Exception as e:
                log(red('Error in model saving, ignored and continuing'))
                stacktrace()
                stop_prog()  # stop it, otherwise multiple lives

        if (epoch + 1) % self.save_latest_ep == 0 and not get_rank():
            try:
                self.save_model(epoch, latest=True)
                self.save_npz(epoch, latest=True)  # for inference and smaller file size
            except Exception as e:
                log(red('Error in model saving, ignored and continuing'))
                stacktrace()
                stop_prog()  # stop it, otherwise multiple lives

        # Perform validation run if required
        if (epoch + 1) % self.eval_ep == 0 and not get_rank():
            try:
                self.test_epoch(epoch + 1)  # will this provoke a live display?
            except Exception as e:
                log(red('Error in validation pass, ignored and continuing'))
                stacktrace()
                stop_prog()  # stop it, otherwise multiple lives
                if not self.ignore_eval_error:
                    raise e

def ConfigurableOptimizer(named_params: Iterator[Tuple[str, nn.Parameter]],

                          # Default parameters
                          lr: float = 5e-3,
                          eps: float = 1e-15,
                          weight_decay: float = 0.0,

                          lr_table: dotdict = dotdict(),  # empty special learning rate table
                          eps_table: dotdict = dotdict(),  # empty table
                          weight_decay_table: dotdict = dotdict(),  # empty table

                          optimizer_cfg: dotdict = dotdict(type=Adam.__name__),
                          ) -> Optimizer:
    if isinstance(named_params, Iterator):
        first = next(named_params)
        if isinstance(first, Tuple):
            named_params = itertools.chain([first], named_params)
        elif isinstance(first, nn.Parameter):
            log(yellow(f'Passed in a list of parameters, assuming they are named sequentially.'))
            named_params = {str(i): first for i, first in enumerate(named_params)}.items()
        else:
            raise NotImplementedError
    elif isinstance(named_params, Dict):
        named_params = named_params.items()
    else:
        raise NotImplementedError

    lr_line = dotdict()
    lr_line.lr = lr
    lr_line.eps = eps
    lr_line.weight_decay = weight_decay
    if lr_line: log('Starting learning rate config:', line(lr_line))

    lr_line = dotdict()
    if len(lr_table): lr_line.lr = lr_table
    if len(eps_table): lr_line.eps = eps_table
    if len(weight_decay_table): lr_line.weight_decay = weight_decay_table
    if lr_line: log('Special learning rate config:', line(lr_line))

    params = []
    for key, value in named_params:
        if not value.requires_grad:
            continue  # skip non-optimizable paramters
        v_lr = lr
        v_eps = eps
        v_weight_decay = weight_decay
        keys = key.split('.')
        for item in keys:
            if item in lr_table:
                v_lr = lr_table[item]
                # log(f'Special lr {key}: {v_lr}')
                break
        for item in keys:
            if item in eps_table:
                v_eps = eps_table[item]
                # log(f'Special eps {key}: {v_eps}')
                break
        for item in keys:
            if item in weight_decay_table:
                v_weight_decay = weight_decay_table[item]
                # log(f'Special weight decay {key}: {v_weight_decay}')
                break
        params.append(
            dotdict(
                params=[value],
                lr=v_lr,
                eps=v_eps,
                weight_decay=v_weight_decay,
                name=item
            )
        )

    if not len(params):
        log(red('optimizer got an empty parameter list, assume you\'re testing'))
        return None

    return OPTIMIZERS.build(optimizer_cfg, params=params)

