def get_distributed():
    if not dist.is_available():
        return False
    if not dist.is_initialized():
        return False
    return True

def get_rank() -> int:
    if not dist.is_available():
        return 0
    if not dist.is_initialized():
        return 0
    return dist.get_rank()

def synchronize():
    """
    Helper function to synchronize (barrier) among all processes when
    using distributed training
    """
    if not dist.is_available():
        return
    if not dist.is_initialized():
        return
    world_size = dist.get_world_size()
    if world_size == 1:
        return
    dist.barrier()

def get_length(args: List, kwargs: Dict):
    for a in args:
        if isinstance(a, list):
            return len(a)
    for v in kwargs.values():
        if isinstance(v, list):
            return len(v)
    raise NotImplementedError

def get_action_args(length: int, args: List, kwargs: Dict, i: int):
    action_args = [(arg[i] if isinstance(arg, list) and len(arg) == length else arg) for arg in args]
    # TODO: Support all types of iterable
    action_kwargs = {key: (kwargs[key][i] if isinstance(kwargs[key], list) and len(kwargs[key]) == length else kwargs[key]) for key in kwargs}
    return action_args, action_kwargs

def read_next_bytes(fid, num_bytes, format_char_sequence, endian_character="<"):
    """Read and unpack the next bytes from a binary file.
    :param fid:
    :param num_bytes: Sum of combination of {2, 4, 8}, e.g. 2, 6, 16, 30, etc.
    :param format_char_sequence: List of {c, e, f, d, h, H, i, I, l, L, q, Q}.
    :param endian_character: Any of {@, =, <, >, !}
    :return: Tuple of read and unpacked values.
    """
    data = fid.read(num_bytes)
    return struct.unpack(endian_character + format_char_sequence, data)

def read_model(path, ext=""):
    # try to detect the extension automatically
    if ext == "":
        if detect_model_format(path, ".bin"):
            ext = ".bin"
        elif detect_model_format(path, ".txt"):
            ext = ".txt"
        else:
            print("Provide model format: '.bin' or '.txt'")
            return

    if ext == ".txt":
        cameras = read_cameras_text(os.path.join(path, "cameras" + ext))
        images = read_images_text(os.path.join(path, "images" + ext))
        points3D = read_points3D_text(os.path.join(path, "points3D") + ext)
    else:
        cameras = read_cameras_binary(os.path.join(path, "cameras" + ext))
        images = read_images_binary(os.path.join(path, "images" + ext))
        points3D = read_points3D_binary(os.path.join(path, "points3D") + ext)
    return cameras, images, points3D

def write_model(cameras, images, points3D, path, ext=".bin"):
    if ext == ".txt":
        write_cameras_text(cameras, os.path.join(path, "cameras" + ext))
        write_images_text(images, os.path.join(path, "images" + ext))
        write_points3D_text(points3D, os.path.join(path, "points3D") + ext)
    else:
        write_cameras_binary(cameras, os.path.join(path, "cameras" + ext))
        write_images_binary(images, os.path.join(path, "images" + ext))
        write_points3d_binary(points3D, os.path.join(path, "points3D") + ext)
    return cameras, images, points3D

def write(self, key, value, dt='mat'):
    if dt == 'mat':
        self._write('{}: !!opencv-matrix'.format(key))
        self._write('  rows: {}'.format(value.shape[0]))
        self._write('  cols: {}'.format(value.shape[1]))
        self._write('  dt: d')
        self._write('  data: [{}]'.format(', '.join(['{:.10f}'.format(i) for i in value.reshape(-1)])))
    elif dt == 'list':
        self._write('{}:'.format(key))
        for elem in value:
            self._write('  - "{}"'.format(elem))
    elif dt == 'real':
        if isinstance(value, np.ndarray):
            value = value.item()
        self._write('{}: {:.10f}'.format(key, value))  # as accurate as possible
    else:
        raise NotImplementedError

