def get_state_dict(state_dict: dotdict, prefix: str = ''):
    if len(prefix) and not prefix.endswith('.'): prefix = prefix + '.'
    d = dotdict()
    for k, v in state_dict.items():
        if k.startswith(prefix):
            d[k[len(prefix):]] = v
    return d

def forward_with_previous(self, input: torch.Tensor):
    x = input
    for i, l in enumerate(self.linears):
        p = x  # store output of previous layer
        if i in self.skips:
            x = torch.cat([x, input], dim=-1)
        if i == len(self.linears) - 1:
            a = self.out_actvn
        else:
            a = self.actvn
        x = a(l(x))  # actual forward
    return x, p

def forward(self, feat: torch.Tensor, batch: dotdict = None):
    if not self.sequential_split:
        feat: torch.Tensor = self.mlp(feat)
        feat = feat.split(self.splits, dim=-1)
    else:
        feat: torch.Tensor = self.mlp.forward_with_previous(feat)
    feat = [self.activs[i](f) for i, f in enumerate(feat)]  # occ, feature
    feat = torch.cat(feat, dim=-1)
    return feat

