def _register_backend(cls, name, backend, force=False, prefixes=None):
    if not isinstance(name, str):
        raise TypeError('the backend name should be a string, '
                        f'but got {type(name)}')
    if not inspect.isclass(backend):
        raise TypeError(
            f'backend should be a class but got {type(backend)}')
    if not issubclass(backend, BaseStorageBackend):
        raise TypeError(
            f'backend {backend} is not a subclass of BaseStorageBackend')
    if not force and name in cls._backends:
        raise KeyError(
            f'{name} is already registered as a storage backend, '
            'add "force=True" if you want to override it')

    if name in cls._backends and force:
        for arg_key, instance in list(cls._instances.items()):
            if isinstance(instance.client, cls._backends[name]):
                cls._instances.pop(arg_key)
    cls._backends[name] = backend

    if prefixes is not None:
        if isinstance(prefixes, str):
            prefixes = [prefixes]
        else:
            assert isinstance(prefixes, (list, tuple))
        for prefix in prefixes:
            if prefix not in cls._prefix_to_backends:
                cls._prefix_to_backends[prefix] = backend
            elif (prefix in cls._prefix_to_backends) and force:
                overridden_backend = cls._prefix_to_backends[prefix]
                if isinstance(overridden_backend, list):
                    overridden_backend = tuple(overridden_backend)
                for arg_key, instance in list(cls._instances.items()):
                    if isinstance(instance.client, overridden_backend):
                        cls._instances.pop(arg_key)
                cls._prefix_to_backends[prefix] = backend
            else:
                raise KeyError(
                    f'{prefix} is already registered as a storage backend,'
                    ' add "force=True" if you want to override it')

def register_handler(file_formats: Union[str, list], **kwargs) -> Callable:

    def wrap(cls):
        _register_handler(cls(**kwargs), file_formats)
        return cls

    return wrap

def wrap(cls):
    _register_handler(cls(**kwargs), file_formats)
    return cls

def _ntuple(n):

    def parse(x):
        if isinstance(x, collections.abc.Iterable):
            return x
        return tuple(repeat(x, n))

    return parse

def parse(x):
    if isinstance(x, collections.abc.Iterable):
        return x
    return tuple(repeat(x, n))

def is_seq_of(seq, expected_type, seq_type=None):
    """Check whether it is a sequence of some type.
    Args:
        seq (Sequence): The sequence to be checked.
        expected_type (type): Expected type of sequence items.
        seq_type (type, optional): Expected sequence type.
    Returns:
        bool: Whether the sequence is valid.
    """
    if seq_type is None:
        exp_seq_type = abc.Sequence
    else:
        assert isinstance(seq_type, type)
        exp_seq_type = seq_type
    if not isinstance(seq, exp_seq_type):
        return False
    for item in seq:
        if not isinstance(item, expected_type):
            return False
    return True

def is_list_of(seq, expected_type):
    """Check whether it is a list of some type.
    A partial method of :func:`is_seq_of`.
    """
    return is_seq_of(seq, expected_type, seq_type=list)

def is_tuple_of(seq, expected_type):
    """Check whether it is a tuple of some type.
    A partial method of :func:`is_seq_of`.
    """
    return is_seq_of(seq, expected_type, seq_type=tuple)

def check_prerequisites(
        prerequisites,
        checker,
        msg_tmpl='Prerequisites "{}" are required in method "{}" but not '
        'found, please install them first.'):  # yapf: disable
    """A decorator factory to check if prerequisites are satisfied.
    Args:
        prerequisites (str of list[str]): Prerequisites to be checked.
        checker (callable): The checker method that returns True if a
            prerequisite is meet, False otherwise.
        msg_tmpl (str): The message template with two variables.
    Returns:
        decorator: A specific decorator.
    """

    def wrap(func):

        @functools.wraps(func)
        def wrapped_func(*args, **kwargs):
            requirements = [prerequisites] if isinstance(
                prerequisites, str) else prerequisites
            missing = []
            for item in requirements:
                if not checker(item):
                    missing.append(item)
            if missing:
                print(msg_tmpl.format(', '.join(missing), func.__name__))
                raise RuntimeError('Prerequisites not meet.')
            else:
                return func(*args, **kwargs)

        return wrapped_func

    return wrap

def _check_py_package(package):
    try:
        import_module(package)
    except ImportError:
        return False
    else:
        return True

def wrap(func):

    @functools.wraps(func)
