        requirements = [prerequisites] if isinstance(
            prerequisites, str) else prerequisites
        missing = []
        for item in requirements:
            if not checker(item):
                missing.append(item)
        if missing:
            print(msg_tmpl.format(', '.join(missing), func.__name__))
            raise RuntimeError('Prerequisites not meet.')
        else:
            return func(*args, **kwargs)

    return wrapped_func

def wrapped_func(*args, **kwargs):
    requirements = [prerequisites] if isinstance(
        prerequisites, str) else prerequisites
    missing = []
    for item in requirements:
        if not checker(item):
            missing.append(item)
    if missing:
        print(msg_tmpl.format(', '.join(missing), func.__name__))
        raise RuntimeError('Prerequisites not meet.')
    else:
        return func(*args, **kwargs)

def call_from_cfg(func: Callable, cfg: dict, **kwargs):
    cfg = dotdict(cfg)
    cfg.update(kwargs)
    func_args = get_func_args(func)
    call_args = dotdict()
    for k, v in func_args.items():
        if v.kind == inspect.Parameter.VAR_KEYWORD:
            call_args = cfg
            break
    if not call_args:  # empty
        for k, v in cfg.items():
            if k not in func_args:
                # Maybe be quite about it
                # log(f'Unused arg:', line(k), '=', line(v), 'for', line(func))
                # FIXME: Easy for undebuggable bugs to slip through (typo in config keys)
                if k not in [BASE_KEY, DELETE_KEY, APPEND_KEY, DEPRECATION_KEY]:
                    if k == '_':
                        pass  # do not warn about placeholders
                    elif k.endswith('_cfg'):
                        log(red(f'Unused cfg:'), line(k), '=', line(v), 'for', line(func))
                    else:
                        log(yellow(f'Unused cfg:'), line(k), '=', line(v), 'for', line(func))
                else:
                    pass  # in case of BASE_KEY, DELETE_KEY, APPEND_KEY, DEPRECATION_KEY
            else: call_args[k] = v
    return func(**call_args)

def __init__(self,
             out_actvn: nn.Module = nn.ReLU(),  # This probably is not the final regressor
             **kwargs,
             ):
    # Inherit from `MlpRegressor`
    call_from_cfg(super().__init__, kwargs, out_actvn=out_actvn)

def __init__(self, name, build_func=None, parent=None, scope=None):
    self._name = name
    self._module_dict = dict()
    self._children = dict()
    self._scope = self.infer_scope() if scope is None else scope

    # self.build_func will be set with the following priority:
    # 1. build_func
    # 2. parent.build_func
    # 3. build_from_cfg
    if build_func is None:
        if parent is not None:
            self.build_func = parent.build_func
        else:
            self.build_func = build_from_cfg
    else:
        self.build_func = build_func
    if parent is not None:
        assert isinstance(parent, Registry)
        parent._add_children(self)
        self.parent = parent
    else:
        self.parent = None

def get(self, key):
    """Get the registry record.

    Args:
        key (str): The class name in string format.

    Returns:
        class: The corresponding class.
    """
    scope, real_key = self.split_scope_key(key)
    if scope is None or scope == self._scope:
        # get from self
        if real_key in self._module_dict:
            return self._module_dict[real_key]
    else:
        # get from self._children
        if scope in self._children:
            return self._children[scope].get(real_key)
        else:
            # goto root
            parent = self.parent
            while parent.parent is not None:
                parent = parent.parent
            return parent.get(key)

def set_default(obj):
    """Set default json values for non-serializable values.

    It helps convert ``set``, ``range`` and ``np.ndarray`` data types to list.
    It also converts ``np.generic`` (including ``np.int32``, ``np.float32``,
    etc.) into plain numbers of plain python built-in types.
    """
    if isinstance(obj, (set, range)):
        return list(obj)
    elif isinstance(obj, np.ndarray):
        return obj.tolist()
    elif isinstance(obj, np.generic):
        return obj.item()
    raise TypeError(f'{type(obj)} is unsupported for json dump')

def dump_to_fileobj(self, obj, file, **kwargs):
    kwargs.setdefault('default', set_default)
    json.dump(obj, file, **kwargs)

def dump_to_str(self, obj, **kwargs):
    kwargs.setdefault('default', set_default)
    return json.dumps(obj, **kwargs)

